window.BOOK={"key":"lamiyyatajam","app":"mutoon-lamiyyatajam","lsk":"mutoon_lamiyyatajam_v1","prefix":"la_","title":"لامية العجم","sub":"الشعر العربي · الطغرائي (ت ٥١٣هـ) · ٥٩ بيتًا","poems":[{"id":"lamiyyatajam","title":"لامية العجم","nazim":"مؤيد الدين أبو إسماعيل الحسين بن علي الطغرائي","death":"ت ٥١٣هـ","meter":"البسيط","source":"جامع الكتب الإسلامية: شرح لامية العجم للدميري (مختصر الغيث المسجم)، تحقيق جميل عويضة","srcUrl":"https://ketabonline.com/ar/books/6545","note":"المتن المسرود في أول شرح الدميري (٥٩ بيتًا)، قوبل كلمةً كلمةً بسكربت بأبيات الشرح نفسه وبشرح البدراني، واعتُمدت قراءة الشرحين حيث اتفقا. النص مشكول جزئيًا (نحو ٤٣٪ من الحروف) لعدم وجود نسخة رقمية مشكولة كاملة، ولم يُزد من الشكل إلا ما في الشرحين أو ما صُحّح لخطأ ظاهر، والتفصيل في تقرير المصادر. وأكمل الذكاء الاصطناعي شكل ما لم يُشكل على الوزن، ويحسن مراجعته.","verses":[["أَصَالَةُ الرَّأْيِ صَانَتْنِي عَنِ الْخَطَلِ","وَحِلْيَةُ الْفَضْلِ زَانَتْنِي لَدَى الْعَطَلِ"],["مَجْدِي أَخِيرًا وَمَجْدِي أَوَّلًا شَرَعٌ","وَالشَّمْسُ رَأْدَ الضُّحَى كَالشَّمْسِ فِي الطَّفَلِ"],["فِيمَ الْإِقَامَةُ بِالزَّوْرَاءِ لَا سَكَنِي","بِهَا وَلَا نَاقَتِي فِيهَا وَلَا جَمَلِي"],["نَاءٍ عَنِ الْأَهْلِ صِفْرُ الْكَفِّ مُنْفَرِدٌ","كَالسَّيْفِ عُرِّيَ مَتْنَاهُ مِنَ الْخَلَلِ"],["فَلَا صَدِيقَ إِلَيْهِ مُشْتَكَى حَزَنِي","وَلَا أَنِيسَ إِلَيْهِ مُنْتَهَى جَذَلِي"],["طَالَ اغْتِرَابِيَ حَتَّى حَنَّ رَاحِلَتِي","وَرَحْلُهَا وَقَرَى الْعَسَّالَةِ الذُّبُلِ"],["وَضَجَّ مِنْ لَغَبٍ نِضْوِي وَعَجَّ لِمَا","يَلْقَى رِكَابِي وَلَجَّ الرَّكْبُ فِي عَذَلِي"],["أُرِيدُ بَسْطَةَ كَفٍّ أَسْتَعِينُ بِهَا","عَلَى قَضَاءِ حُقُوقٍ لِلْعُلَى قِبَلِي"],["وَالدَّهْرُ يَعْكِسُ آمَالِي وَيُقْنِعُنِي","مِنَ الْغَنِيمَةِ بَعْدَ الْكَدِّ بِالْقَفَلِ"],["وَذِي شِطَاطٍ كَصَدْرِ الرُّمْحِ مُعْتَقِلٍ","لِمِثْلِهِ غَيْرَ هَيَّابٍ وَلَا وَكِلِ"],["حُلْوِ الْفُكَاهَةِ مُرِّ الْجِدِّ قَدْ مُزِجَتْ","بِقَسْوَةِ الْبَأْسِ فِيهِ رِقَّةُ الْغَزَلِ"],["طَرَدْتُ سَرْحَ الْكَرَى عَنْ وِرْدِ مُقْلَتِهِ","وَاللَّيْلُ أَغْرَى سَوَامَ النَّوْمِ بِالْمُقَلِ"],["وَالرَّكْبُ مِيلٌ عَلَى الْأَكْوَارِ مِنْ طَرِبٍ","صَاحٍ وَآخَرَ مِنْ خَمْرِ الْهَوَى ثَمِلِ"],["فَقُلْتُ أَدْعُوكَ لِلْجُلَّى لِتَنْصُرَنِي","وَأَنْتَ تَخْذُلُنِي فِي الْحَادِثِ الْجَلَلِ"],["تَنَامُ عَيْنِي وَعَيْنُ النَّجْمِ سَاهِرَةٌ","وَتَسْتَحِيلُ وَصِبْغُ اللَّيْلِ لَمْ يَحُلِ"],["فَهَلْ تُعِينُ عَلَى غَيٍّ هَمَمْتُ بِهِ","وَالْغَيُّ يَزْجُرُ أَحْيَانًا عَنِ الْفَشَلِ"],["إِنِّي أُرِيدُ طُرُوقَ الْحَيِّ مِنْ إِضَمٍ","وَقَدْ حَمَاهُ رُمَاةُ الْحَيِّ مِنْ ثُعَلِ"],["يَحْمُونَ بِالْبِيضِ وَالسُّمْرِ اللِّدَانِ بِهِمْ","سُودَ الْغَدَائِرِ حُمْرَ الْحَلْيِ وَالْحُلَلِ"],["فَسِرْ بِنَا فِي ذِمَامِ اللَّيْلِ مُعْتَسِفًا","بِنَفْحَةِ الطِّيبِ تَهْدِينَا إِلَى الْحِلَلِ"],["فَالْحِبُّ حَيْثُ الْعِدَى وَالْأُسْدُ رَابِضَةٌ","حَوْلَ الْكِنَاسِ لَهَا غَابٌ مِنَ الْأَسَلِ"],["نَؤُمُّ نَاشِئَةً بِالْجِزْعِ قَدْ سُقِيَتْ","نِصَالُهَا بِمِيَاهِ الْغُنْجِ وَالْكَحَلِ"],["قَدْ زَادَ طِيبَ أَحَادِيثِ الْكِرَامِ بِهَا","مَا بِالْكَرَائِمِ مِنْ جُبْنٍ وَمِنْ بُخُلِ"],["تَبِيتُ نَارُ الْهَوَى مِنْهُنَّ فِي كَبِدٍ","حَرَّى وَنَارُ الْقِرَى مِنْهُمْ عَلَى الْقُلَلِ"],["يَقْتُلْنَ أَنْضَاءَ حُبٍّ لَا حَرَاكَ بِهَا","وَيَنْحَرُونَ كِرَامَ الْخَيْلِ وَالْإِبِلِ"],["يُشْفَى لَدِيغُ الْعَوَالِي فِي بُيُوتِهِمُ","بِنَهْلَةٍ مِنْ غَدِيرِ الْخَمْرِ وَالْعَسَلِ"],["لَعَلَّ إِلْمَامَةً بِالْجِزْعِ ثَانِيَةً","يَدِبُّ فِيهَا نَسِيمُ الْبُرْءِ فِي عِلَلِ"],["لَا أَكْرَهُ الطَّعْنَةَ النَّجْلَاءَ قَدْ شُفِعَتْ","بِرَشْقَةٍ مِنْ نِبَالِ الْأَعْيُنِ النُّجُلِ"],["وَلَا أَهَابُ صِفَاحَ الْبِيضِ تُسْعِدُنِي","بِاللَّمْحِ مِنْ خَلَلِ الْأَسْتَارِ وَالْكِلَلِ"],["وَلَا أُخِلُّ بِغِزْلَانٍ أُغَازِلُهَا","وَلَوْ دَهَتْنِي أُسُودُ الْغِيلِ بِالْغِيَلِ"],["حُبُّ السَّلَامَةِ يَثْنِي هَمَّ صَاحِبِهِ","عَنِ الْمَعَالِي وَيُغْرِي الْمَرْءَ بِالْكَسَلِ"],["فَإِنْ جَنَحْتَ إِلَيْهِ فَاتَّخِذْ نَفَقًا","فِي الْأَرْضِ أَوْ سُلَّمًا فِي الْجَوِّ فَاعْتَزِلِ"],["وَدَعْ غِمَارَ الْعُلَى لِلْمُقْدِمِينَ عَلَى","رُكُوبِهَا وَاقْتَنِعْ مِنْهُنَّ بِالْبَلَلِ"],["رِضَى الذَّلِيلِ بِخَفْضِ الْعَيْشِ مَسْكَنَةٌ","وَالْعِزُّ عِنْدَ رَسِيمِ الْأَيْنُقِ الذُّلُلِ"],["فَادْرَأْ بِهَا فِي نُحُورِ الْبِيدِ جَافِلَةً","مُعَارِضَاتٍ مَثَانِى اللُّجْمِ بِالْجُدَلِ"],["إِنَّ الْعُلَى حَدَّثَتْنِي وَهْيَ صَادِقَةٌ","فِي مَا تُحَدِّثُ أَنَّ الْعِزَّ فِي النُّقَلِ"],["لَوْ أَنَّ فِي شَرَفِ الْمَأْوَى بُلُوغَ مُنًى","لَمْ تَبْرَحِ الشَّمْسُ يَوْمًا دَارَةَ الْحَمَلِ"],["أَهَبْتُ بِالْحَظِّ لَوْ نَادَيْتُ مُسْتَمِعًا","وَالْحَظُّ عَنِّيَ بِالْجُهَّالِ فِي شُغُلِ"],["لَعَلَّهُ إِنْ بَدَا فَضْلِي وَنَقْصُهُمُ","لِعَيْنِهِ نَامَ عَنْهُمْ أَوْ تَنَبَّهَ لِي"],["أُعَلِّلُ النَّفْسَ بِالْآمَالِ أَرْقُبُهَا","مَا أَضْيَقَ الْعَيْشَ لَوْلَا فُسْحَةُ الْأَمَلِ"],["لَمْ أَرْتَضِ الْعَيْشَ وَالْأَيَّامُ مُقْبِلَةٌ","فَكَيْفَ أَرْضَى وَقَدْ وَلَّتْ عَلَى عَجَلِ"],["غَالَى بِنَفْسِيَ عِرْفَانِي بِقِيمَتِهَا","فَصُنْتُهَا عَنْ رَخِيصِ الْقَدْرِ مُبْتَذَلِ"],["وَعَادَةُ النَّصْلِ أَنْ يُزْهَى بِجَوْهَرِهِ","وَلَيْسَ يَعْمَلُ إِلَّا فِي يَدَيْ بَطَلِ"],["مَا كُنْتُ أُوثِرُ أَنْ يَمْتَدَّ بِي زَمَنِي","حَتَّى أَرَى دَوْلَةَ الْأَوْغَادِ وَالسَّفَلِ"],["تَقَدَّمَتْنِي أُنَاسٌ كَانَ شَوْطُهُمُ","وَرَاءَ خَطْوِيَ إِذْ أَمْشِي عَلَى مَهَلِ"],["هَذَا جَزَاءُ امْرِئٍ أَقْرَانُهُ دَرَجُوا","مِنْ قَبْلِهِ فَتَمَنَّى فُسْحَةَ الْأَجَلِ"],["وَإِنْ عَلَانِيَ مَنْ دُونِي فَلَا عَجَبٌ","لِي أُسْوَةٌ بِانْحِطَاطِ الشَّمْسِ عَنْ زُحَلِ"],["فَاصْبِرْ لَهَا غَيْرَ مُحْتَالٍ وَلَا ضَجِرٍ","فِي حَادِثِ الدَّهْرِ مَا يُغْنِي عَنِ الْحِيَلِ"],["أَعْدَى عَدُوِّكَ أَدْنَى مَنْ وَثِقْتَ بِهِ","فَحَاذِرِ النَّاسَ وَاصْحَبْهُمْ عَلَى دَخَلِ"],["وَإِنَّمَا رَجُلُ الدُّنْيَا وَوَاحِدُهَا","مَنْ لَا يُعَوِّلُ فِي الدُّنْيَا عَلَى رَجُلِ"],["وَحُسْنُ ظَنِّكَ بِالْأَيَّامِ مَعْجَزَةٌ","فَظُنَّ شَرًّا وَكُنْ مِنْهَا عَلَى وَجَلِ"],["غَاضَ الْوَفَاءُ وَفَاضَ الْغَدْرُ وَانْفَرَجَتْ","مَسَافَةُ الْخُلْفِ بَيْنَ الْقَوْلِ وَالْعَمَلِ"],["وَشَانَ صِدْقَكَ عِنْدَ النَّاسِ كِذْبُهُمُ","وَهَلْ يُطَابَقُ مُعْوَجٌّ بِمُعْتَدِلِ"],["إِنْ كَانَ يَنْجَعُ شَيْءٌ فِي ثَبَاتِهِمُ","عَلَى الْعُهُودِ فَسَبْقُ السَّيْفِ لِلْعَذَلِ"],["يَا وَارِدًا سُؤْرَ عَيْشٍ كُلُّهُ كَدَرٌ","أَنْفَقْتَ عُمْرَكَ فِي أَيَّامِكَ الْأُوَلِ"],["فِيمَ اقْتِحَامُكَ لُجَّ الْبَحْرِ تَرْكَبُهُ","وَأَنْتَ تَكْفِيكَ مِنْهُ مَصَّةُ الْوَشَلِ"],["مُلْكُ الْقَنَاعَةِ لَا يُخْشَى عَلَيْهِ وَلَا","يُحْتَاجُ فِيهِ إِلَى الْأَنْصَارِ وَالْخَوَلِ"],["تَرْجُو الْبَقَاءَ بِدَارٍ لَا ثَبَاتَ لَهَا","فَهَلْ سَمِعْتَ بِظِلٍّ غَيْرِ مُنْتَقِلِ"],["وَيَا خَبِيرًا عَلَى الْأَسْرَارِ مُطَّلِعًا","اصْمُتْ فَفِي الصَّمْتِ مَنْجَاةٌ مِنَ الزَّلَلِ"],["قَدْ رَشَّحُوكَ لِأَمْرٍ إِنْ فَطِنْتَ لَهُ","فَارْبَأْ بِنَفْسِكَ أَنْ تَرْعَى مَعَ الْهَمَلِ"]],"secs":{"1":"لَامِيَّةُ الْعَجَمِ"}}],"sharh":false};
